update sys_user_notification_push_outbox
set status = #{status}, last_result = #{lastResult}, next_attempt_at = #{nextAttemptAt},
    version = version + 1, updated_time = #{now}
where outbox_id = #{outboxId} and status = 'SENDING' and version = #{version}
